#!/usr/bin/env python3
"""Delete artifacts generated by ``main.py`` and the dataset pipeline (project root).

Destructive counterpart of ``main.py``. Bare ``python clean.py`` prints help and
deletes nothing. ``--dry-run`` previews; ``--run`` deletes after a confirmation
prompt (``--yes`` skips it). Placeholders (``.gitkeep``, ``__init__.py``), configs,
source, reference data and docs are never touched.

Examples:

    # Preview everything that would be deleted (all phases, PDFs and caches kept)
    python clean.py --dry-run

    # Delete all generated outputs, keep FIA PDFs and API caches (prompts first)
    python clean.py --run

    # Single phase / several phases
    python clean.py --run --only v1
    python clean.py --run --only v2 --only nlp
    python clean.py --run --only normative

    # A phase plus everything built from it (mirrors main.py --from)
    python clean.py --run --from v1            # v1 -> v2 -> nlp -> normative
    python clean.py --run --from dataset       # everything except PDFs and caches

    # Dataset outputs, optionally per stage and/or season
    python clean.py --run --only dataset
    python clean.py --run --only dataset --season 2020 --season 2021
    python clean.py --run --dataset-stage enrich --dataset-stage validate
    python clean.py --run --only dataset --season 2026 --include-pdfs

    # Hard-to-recreate data (opt-in; requires typing 'yes')
    python clean.py --run --only dataset --include-cache   # Ergast / FastF1 / OpenF1
    python clean.py --run --purge                          # literally everything

    # Show every file instead of a preview
    python clean.py --dry-run --from v1 --list

Phases (same names as main.py):

    dataset    data/interim/extracted_documents/, dataset/csv/*, enrichment_meta,
               reports/tables/, enrichment reports
               stages: download (opt-in) | parse | build | enrich | validate
    v1         data/processed/{incidents,features,train,validation,test}.parquet,
               ml_models/{preprocessor.*,xgboost/,baseline/}, V1 figures + report
    v2         data/processed/*_v2.parquet, ml_models/{preprocessor_xgboost_v2.*,
               xgboost_v2/}, ablation/selection JSON, V2 figures + report
    nlp        data/processed/nlp_*.jsonl, ml_models/nlp/ (model, tokenizer,
               checkpoints), NLP figure + training/fusion reports
    normative  incidents_with_normative.parquet, ml_models/normative/,
               reports/normative/

Implementation: ``src/fia_ml/cleanup.py``.
"""

from __future__ import annotations

import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent
SRC_ROOT = PROJECT_ROOT / "src"
if str(SRC_ROOT) not in sys.path:
    sys.path.insert(0, str(SRC_ROOT))

# Must follow the sys.path setup above, so it cannot sit at the top of the module.
from fia_ml.cleanup import main  # pylint: disable=wrong-import-position

if __name__ == "__main__":
    raise SystemExit(main())
